mapper.select:
SELECT PY.PYMNT_ID , PY.PJ_ID , PY.GRNT_AMT , PY.CNTRCT_AMT , TO_CHAR(PY.GRNT_PD_DT,'YYYY-MM-DD') GRNT_PD_DT , TO_CHAR(PY.CNTRCT_PD_DT,'YYYY-MM-DD') CNTRCT_PD_DT , PY.ACCNT_NM , PY.PYMNT_TYP , PY.IMP_UID , PY.DPST_RFND_AMNT , TO_CHAR(PY.DPST_RFND_DT,'YYYY-MM-DD') DPST_RFND_DT , PJ.PJ_TTL , PJ.OBTN_ID FROM PYMNT_INFO PY JOIN PJ_INFO PJ ON PY.PJ_ID = PJ.PJ_ID WHERE PJ.ORDR_ID = #{emilAddr}
AND PY.GRNT_PD_DT IS NOT NULL AND PY.GRNT_PD_DT > TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND PY.CNTRCT_PD_DT IS NOT NULL AND PY.CNTRCT_PD_DT > TO_DATE(#{startDate}, 'YYYY-MM-DD')
